def ph(n,o,peak,pl,dur,after,nd,onset_feel):
    return [f"{n} usually begins {o}, {onset_feel}.","The effect builds over the next stretch.",f"The peak is {peak}.",f"A plateau of {pl}.",f"Effects fade over {dur}.",after,nd]
def tm(o,p,pl,dur): return [o,"after onset",p,pl,dur,"hours after","next day"]
