for (slug,name,cls,brands,hist,medu,legal,char,o,of,pk,pl,dur,after,nd,route,od) in OP:
    n=name.split(" (")[0]
    RX.R(slug,name,cls,brands,hist,medu,"Misuse is uncommon or limited; most encounters today are accidental or through contaminated street drugs." if slug in("fentanyl-analogs","brorphine","ap-237","etorphine") else "Misuse has been limited compared with common opioids.",legal,
      [f"{n}'s character is {char}.","Like all mu-opioid agonists, it slows breathing, and that risk rises sharply with alcohol, benzodiazepines, gabapentinoids, or other sedatives.","Tolerance and dependence develop with regular use."],
      ph(n,o,pk,pl,dur,after,nd,of),{route:"See general notes."},"Other routes are not covered.",od,[f"DEA Controlled Substance Schedules (21 CFR 1308) entry for {n}","UNODC: Single Convention on Narcotic Drugs 1961, schedules"],times={route:tm(o.replace("within ",""),pk if len(pk)<20 else "peak",pl,dur)})
    if slug in("fentanyl-analogs","brorphine","etorphine"): D[slug]["also"]=["xyl"]; D[slug]["cat"]="nso"
