for slug,name,brands,hist,legal,char,(o,p,dur),cat in BZL:
    n=name.split(" (")[0]
    BZ.B(slug,name,("Designer ('research chemical') benzodiazepine; little or no human research." if cat=="rcbenzo" else "Benzodiazepine (or close relative) prescribed in some countries."),brands,hist,
      "None approved." if cat=="rcbenzo" else "Anxiety, sleep, or muscle spasm in the countries where it is sold.",
      "Sold online or in fake tablets." if cat=="rcbenzo" else "Misuse is limited outside the countries where it is prescribed.",legal,
      [f"{n}'s character is {char}.","Combined with opioids or alcohol, it can stop breathing, and memory loss is common.","Daily use leads to dependence, and stopping suddenly can cause seizures."],
      [f"{n} usually begins within about {o}.","Calm and heaviness build.",f"The peak, around {p}, brings {char}.","A plateau of several hours.",f"Effects fade over {dur}.","Drowsiness and memory gaps.","Next-day grogginess is common with longer-acting drugs."],
      {"oral":"Tablets, capsules, or (for designer drugs) powders and pellets."},"Other routes are not covered.","Dangerous with opioids, alcohol, and other sedatives; overdose signs include being unable to wake and slowed breathing.",
      [f"DEA Controlled Substance Schedules entry for {n}" if "Schedule" in legal else f"National formulary entry for {n}","UNODC: Convention on Psychotropic Substances 1971, schedules"],times={"oral":[o,"after onset",p,"several hours",dur,"hours after","next day"]},cat=cat)
